var e=[`Jan`,`Feb`,`Mar`,`Apr`,`May`,`Jun`,`Jul`,`Aug`,`Sep`,`Oct`,`Nov`,`Dec`];function t(t){if(!t)return`-`;try{let n=(typeof t==`string`?t.trim():t.toISOString()).split(`T`)[0].split(`-`);if(n.length===3){let t=n[0],r=parseInt(n[1],10)-1,i=n[2].padStart(2,`0`);if(r>=0&&r<12)return`${i}/${e[r]}/${t}`}let r=new Date(t);return isNaN(r.getTime())?String(t):`${String(r.getDate()).padStart(2,`0`)}/${e[r.getMonth()]}/${r.getFullYear()}`}catch{return String(t)}}export{t};